{
  "lines": [
    {
      "id": "variety.stretch_seconds",
      "tiers": [
        {
          "id": "variety.stretch_seconds:t1",
          "title": "Первый вдох гармошки",
          "phrase": "Ты накопил 300 секунд растяжки в сохранённых упражнениях. Гармошка одобряет: наконец-то кто-то разделяет её увлечение.",
          "imagePrompt": "A little accordion with mitten hands opens its first bellows folds beside a neatly unrolled exercise mat. One foot steadies the mat while the other points forward, giving the instrument the earnest air of someone testing a new hobby.",
          "fishMarkup": "[warm] Ты накопил 300 секунд растяжки в сохранённых упражнениях. Гармошка одобряет: наконец-то кто-то разделяет её увлечение.",
          "audioText": "Ты накопил 300 секунд растяжки в сохранённых упражнениях. Гармошка одобряет: наконец-то кто-то разделяет её увлечение."
        },
        {
          "id": "variety.stretch_seconds:t2",
          "title": "Купе для складок",
          "phrase": "В твоей истории уже 1800 секунд растяжки из сохранённых упражнений. Гармошка развернулась так основательно, что просит отдельное купе.",
          "imagePrompt": "The little accordion pulls its bellows wide enough to form a tiny train compartment. A kettlebell passenger lounges on a built-in bench, while the accordion leans outward like a conductor surprised by the size of the carriage.",
          "fishMarkup": "[confident] В твоей истории уже <emphasis>1800 секунд растяжки</emphasis> из сохранённых упражнений. Гармошка развернулась так основательно, что просит отдельное купе.",
          "audioText": "В твоей истории уже 1800 секунд растяжки из сохранённых упражнений. Гармошка развернулась так основательно, что просит отдельное купе."
        },
        {
          "id": "variety.stretch_seconds:t3",
          "title": "Чайная на растяжке",
          "phrase": "В сохранённых упражнениях ты накопил 7200 секунд растяжки. Гармошка развернулась — и открыла чайную для гирь.",
          "imagePrompt": "The little accordion has unfolded its bellows into a long tea counter. It pours from a squat teapot for kettlebells perched on stools, with saucers tucked between the folds; the smallest kettlebell solemnly lifts an oversized cup.",
          "fishMarkup": "[triumphant] В сохранённых упражнениях ты накопил 7200 секунд растяжки. Гармошка развернулась — <slow>и открыла</slow> <emphasis>чайную для гирь</emphasis>.",
          "audioText": "В сохранённых упражнениях ты накопил 7200 секунд растяжки. Гармошка развернулась — и открыла чайную для гирь."
        }
      ]
    },
    {
      "id": "variety.stretch_days",
      "tiers": [
        {
          "id": "variety.stretch_days:t1",
          "title": "Черепаший дебют",
          "phrase": "Ты накопил 3 дня с сохранённой растяжкой. Черепаха выкатывает коврик — спешка сюда не записана.",
          "imagePrompt": "A small turtle with an exercise mat strapped across its shell gently pushes the loose end open beside a tiny sprout. Its front feet flatten the first corner while the remaining roll towers comically over its head.",
          "fishMarkup": "[warm] Ты накопил 3 дня с сохранённой растяжкой. Черепаха выкатывает коврик — <soft>спешка сюда не записана</soft>.",
          "audioText": "Ты накопил 3 дня с сохранённой растяжкой. Черепаха выкатывает коврик — спешка сюда не записана."
        },
        {
          "id": "variety.stretch_days:t2",
          "title": "Коврик обживает пол",
          "phrase": "У тебя накопилось 10 дней с сохранённой растяжкой. Черепаха прижала коврик камушками: теперь это почти недвижимость.",
          "imagePrompt": "The small turtle anchors a longer exercise mat with smooth pebbles, carefully nudging the last pebble into place. A rolled spare mat rests across its shell, and its satisfied stance suggests a property owner inspecting a new home.",
          "fishMarkup": "[playful] У тебя накопилось 10 дней с сохранённой растяжкой. Черепаха прижала коврик камушками: теперь это <emphasis>почти недвижимость</emphasis>.",
          "audioText": "У тебя накопилось 10 дней с сохранённой растяжкой. Черепаха прижала коврик камушками: теперь это почти недвижимость."
        },
        {
          "id": "variety.stretch_days:t3",
          "title": "Студия на панцире",
          "phrase": "За всё время ты собрал 25 дней с сохранённой растяжкой. Черепаха ставит навес: у коврика теперь свой адрес.",
          "imagePrompt": "The small turtle balances a rolled mat on its shell while raising a plain fabric canopy over its exercise spot. It braces a canopy pole with one foot; neatly stacked mats and a low empty shelf mark the beginnings of a tiny studio.",
          "fishMarkup": "[confident] За всё время ты собрал <emphasis>25 дней</emphasis> с сохранённой растяжкой. Черепаха ставит навес: у коврика теперь свой адрес.",
          "audioText": "За всё время ты собрал 25 дней с сохранённой растяжкой. Черепаха ставит навес: у коврика теперь свой адрес."
        },
        {
          "id": "variety.stretch_days:t4",
          "title": "Место для размаха",
          "phrase": "У тебя в копилке уже 50 дней с сохранённой растяжкой. Черепаха раскатывает большой коврик — ждёт очень домашнего гостя.",
          "imagePrompt": "The small turtle rolls a broad exercise mat out from beneath its completed canopy, creating a landing space far larger than itself. With a spare mat tucked across its shell, it peers expectantly toward an approaching sofa-shaped shadow.",
          "fishMarkup": "[excited] У тебя в копилке уже <emphasis>50 дней</emphasis> с сохранённой растяжкой. Черепаха раскатывает большой коврик — ждёт очень домашнего гостя.",
          "audioText": "У тебя в копилке уже 50 дней с сохранённой растяжкой. Черепаха раскатывает большой коврик — ждёт очень домашнего гостя."
        },
        {
          "id": "variety.stretch_days:t5",
          "title": "Диван тоже записался",
          "phrase": "Ты накопил 100 дней с сохранённой растяжкой. Черепаха открыла студию — и записала туда диван.",
          "imagePrompt": "The small turtle proudly welcomes a sleepy sofa onto an enormous exercise mat beneath its canopy. The sofa stretches its short wooden legs while a loose cushion yawns; the turtle holds a second mat, clearly wondering where to put it.",
          "fishMarkup": "[triumphant] Ты накопил 100 дней с сохранённой растяжкой. Черепаха открыла студию — <slow>и записала туда</slow> <emphasis>диван</emphasis>.",
          "audioText": "Ты накопил 100 дней с сохранённой растяжкой. Черепаха открыла студию — и записала туда диван."
        }
      ]
    }
  ]
}
